uint32_t Hash(const char* data, size_t n, uint32_t seed) {
    uint32_t h = seed;
    const uint32_t c1 = 0xcc9e2d51;
    const uint32_t c2 = 0x1b873593;
    const uint32_t r1 = 15;
    const uint32_t r2 = 13;
    const uint32_t m = 5;
    const uint32_t n1 = 0xe6546b64;

    for (size_t i = 0; i < n; i += 4) {
        uint32_t w = 0;
        for (int j = 0; j < 4; j++) {
            if (i + j < n) {
                w |= (static_cast<uint32_t>(data[i + j]) << (j * 8));
            }
        }
        w *= c1;
        w = (w << r1) | (w >> (32 - r1));
        w *= c2;
        h ^= w;
        h = (h << r2) | (h >> (32 - r2));
        h = h * m + n1;
    }

    if (n & 3) {
        uint32_t w = 0;
        for (int j = 0; j < (n & 3); j++) {
            w |= (static_cast<uint32_t>(data[n - 1 - j]) << (j * 8));
        }
        w *= c1;
        w = (w << r1) | (w >> (32 - r1));
        w *= c2;
        h ^= w;
    }

    h ^= n;
    h ^= (h >> 16);
    h *= 0x85ebca6b;
    h ^= (h >> 13);
    h *= 0xc2b2ae35;
    h ^= (h >> 16);

